# Hindi / Gujarati text for Economics Ch 3 lesson, sections 4-6.
TEXT_B = {
 "s4.thm.title": ("कौन क़र्ज़ देता है, किन शर्तों पर, और किसे", "કોણ લોન આપે છે, કઈ શરતોએ, અને કોને"),
 "s4.thm.body": (
  "**ऋण व्यवस्थाओं के विभिन्न रूप (सोनपुर गाँव):**\n"
  "- छोटा किसान **श्यामल** खेती के लिए गाँव के **साहूकार** से **5 प्रतिशत मासिक** (यानी **60 प्रतिशत सालाना**) ब्याज पर क़र्ज़ लेता है।\n"
  "- खेतिहर मज़दूर **रमा** अपने **नियोक्ता**, एक भूस्वामी, से 5 प्रतिशत मासिक पर क़र्ज़ लेती है और उसके लिए कम मज़दूरी पर **काम करके** चुकाती है; वह क़र्ज़ में फँसी है।\n"
  "- ज़्यादा ज़मीन वाले **अरुण** को अपनी ज़मीन ज़मानत रखकर **8.5 प्रतिशत सालाना** पर **बैंक ऋण** मिलता है, जो **तीन साल** में चुकाना है।\n"
  "- किसान **कृषक सहकारी समिति** से भी क़र्ज़ ले सकते हैं, जो सदस्यों की जमा लेती है और उन्हें उचित दर पर क़र्ज़ देती है।\n\n"
  "**औपचारिक क्षेत्रक के ऋण:** **बैंकों और सहकारी समितियों** से मिलने वाले ऋण। **भारतीय रिज़र्व बैंक** ऋणों के औपचारिक स्रोतों की कार्यप्रणाली पर **नज़र रखता** है: वह देखता है कि बैंक अपनी जमा का **न्यूनतम नक़द शेष** रखें, और ऋण केवल लाभ कमाने वाले व्यापारियों को ही नहीं, बल्कि **छोटे किसानों, लघु उद्योगों और छोटे कर्ज़दारों** को भी दें। बैंकों को RBI को बताना होता है कि वे कितना ऋण, किसे और किस ब्याज दर पर दे रहे हैं।\n\n"
  "**अनौपचारिक क्षेत्रक के ऋण:** **साहूकार, व्यापारी, मालिक, रिश्तेदार और दोस्तों** से मिलने वाले ऋण। उनकी ऋण गतिविधियों की देखरेख करने वाली **कोई संस्था नहीं** है। वे जिस भी ब्याज दर पर चाहें, ऋण दे सकते हैं, और अपना पैसा वापस पाने के लिए **अनुचित तरीक़े** अपनाने से उन्हें रोकने वाला कोई नहीं। अनौपचारिक ऋणदाता **बहुत ऊँची ब्याज दर** लेते हैं, इसलिए कर्ज़दार की कमाई का बड़ा हिस्सा ऋण चुकाने में जाता है, और वह **क़र्ज़-जाल** में फँस सकता है।\n\n"
  "**औपचारिक ऋण का विस्तार क्यों ज़रूरी:** सस्ता और सामर्थ्य के अनुकूल ऋण देश के विकास के लिए बहुत ज़रूरी है।\n"
  "- अनौपचारिक स्रोतों से **ऋण की ऊँची लागत** का अर्थ है कि कर्ज़दार की आय का ज़्यादा हिस्सा ऋण चुकाने में जाता है, और उसके पास कम बचता है (जैसे श्यामल)।\n"
  "- ऊँची ब्याज दर के कारण चुकाई जाने वाली रक़म कर्ज़दार की **आय से ज़्यादा** हो सकती है, जिससे **क़र्ज़ बढ़ता** जाता है (जैसे रमा)।\n"
  "- जो लोग ऋण लेकर **उद्यम शुरू** करना चाहते हैं, वे ऋण की ऊँची लागत के कारण ऐसा नहीं कर पाते।\n"
  "- इसलिए बैंकों और सहकारी समितियों को, ख़ासकर ग्रामीण क्षेत्रों में, **ज़्यादा ऋण** देना चाहिए ताकि अनौपचारिक स्रोतों पर निर्भरता घटे। औपचारिक ऋण **ग़रीबों** तक भी पहुँचना चाहिए, केवल अमीरों तक नहीं। औपचारिक क्षेत्रक आज भी ग्रामीण लोगों की कुल ऋण ज़रूरतों का केवल लगभग **आधा** पूरा करता है।\n\n"
  "**किसे क्या मिलता है?** **अमीर परिवार** अपने अधिकतर ऋण **औपचारिक स्रोतों** से पाते हैं, जबकि **ग़रीब परिवार** मुख्यतः **अनौपचारिक स्रोतों** पर निर्भर हैं। ग़रीबों के पास अक्सर **ज़मानत** और बैंकों को चाहिए **काग़ज़ात** नहीं होते, और बैंकों को बहुत से छोटे ऋण देना महँगा लगता है।",
  "**ધિરાણ વ્યવસ્થાનાં વિવિધ સ્વરૂપો (સોનપુર ગામ):**\n"
  "- નાનો ખેડૂત **શ્યામલ** ખેતી માટે ગામના **શાહુકાર** પાસેથી **5 ટકા માસિક** (એટલે કે **60 ટકા વાર્ષિક**) વ્યાજે લોન લે છે.\n"
  "- ખેતમજૂર **રમા** પોતાના **માલિક**, એક જમીનદાર, પાસેથી 5 ટકા માસિક વ્યાજે લોન લે છે અને તેના માટે ઓછા વેતને **કામ કરીને** ચૂકવે છે; તે દેવામાં ફસાયેલી છે.\n"
  "- વધુ જમીનવાળા **અરુણ**ને પોતાની જમીન તારણ તરીકે આપી **8.5 ટકા વાર્ષિક** વ્યાજે **બૅન્ક લોન** મળે છે, જે **ત્રણ વર્ષ**માં ચૂકવવાની છે.\n"
  "- ખેડૂતો **કૃષક સહકારી મંડળી** પાસેથી પણ લોન લઈ શકે, જે સભ્યોની થાપણો લે છે અને તેમને વાજબી દરે લોન આપે છે.\n\n"
  "**ઔપચારિક ક્ષેત્રની શાખ:** **બૅન્કો અને સહકારી મંડળીઓ** પાસેથી મળતી લોન. **ભારતીય રિઝર્વ બૅન્ક** લોનના ઔપચારિક સ્રોતોની કામગીરી પર **દેખરેખ રાખે** છે: તે જુએ છે કે બૅન્કો પોતાની થાપણોમાંથી **લઘુતમ રોકડ જથ્થો** રાખે, અને લોન ફક્ત નફો કમાતા વેપારીઓને જ નહિ, પણ **નાના ખેડૂતો, નાના ઉદ્યોગો અને નાના દેવાદારો**ને પણ આપે. બૅન્કોએ RBIને જણાવવું પડે છે કે તેઓ કેટલું ધિરાણ, કોને અને કયા વ્યાજ દરે આપે છે.\n\n"
  "**અનૌપચારિક ક્ષેત્રની શાખ:** **શાહુકારો, વેપારીઓ, માલિકો, સગાં અને મિત્રો** પાસેથી મળતી લોન. તેમની ધિરાણ પ્રવૃત્તિઓ પર દેખરેખ રાખતી **કોઈ સંસ્થા નથી**. તેઓ ગમે તે વ્યાજ દરે ધિરાણ આપી શકે, અને પોતાના પૈસા પાછા મેળવવા **અયોગ્ય રીતો** અપનાવતાં તેમને રોકનાર કોઈ નથી. અનૌપચારિક ધિરાણકર્તાઓ **ઘણો ઊંચો વ્યાજ દર** લે છે, તેથી દેવાદારની કમાણીનો મોટો ભાગ લોન ચૂકવવામાં જાય છે, અને તે **દેવાની જાળ**માં ફસાઈ શકે.\n\n"
  "**ઔપચારિક શાખનો વિસ્તાર કેમ જરૂરી:** સસ્તી અને પરવડે તેવી શાખ દેશના વિકાસ માટે ખૂબ જરૂરી છે.\n"
  "- અનૌપચારિક સ્રોતોમાંથી **ઉછીના લેવાનો ઊંચો ખર્ચ** એટલે દેવાદારની આવકનો વધુ ભાગ લોન ચૂકવવામાં જાય છે, અને તેની પાસે ઓછું બચે છે (જેમ કે શ્યામલ).\n"
  "- ઊંચા વ્યાજ દરને કારણે ચૂકવવાની રકમ દેવાદારની **આવક કરતાં વધુ** થઈ શકે, જેથી **દેવું વધતું** જાય (જેમ કે રમા).\n"
  "- જે લોકો લોન લઈને **ધંધો શરૂ** કરવા ઇચ્છે છે, તેઓ ઉછીના લેવાના ઊંચા ખર્ચને કારણે તેમ કરી શકતા નથી.\n"
  "- તેથી બૅન્કો અને સહકારી મંડળીઓએ, ખાસ કરીને ગ્રામીણ વિસ્તારોમાં, **વધુ ધિરાણ** આપવું જોઈએ જેથી અનૌપચારિક સ્રોતો પરનો આધાર ઘટે. ઔપચારિક ધિરાણ **ગરીબો** સુધી પણ પહોંચવું જોઈએ, ફક્ત ધનિકો સુધી નહિ. ઔપચારિક ક્ષેત્ર હજી ગ્રામીણ લોકોની કુલ ધિરાણ જરૂરિયાતોનો ફક્ત આશરે **અડધો** ભાગ પૂરો કરે છે.\n\n"
  "**કોને શું મળે છે?** **ધનિક પરિવારો** પોતાનું મોટા ભાગનું ધિરાણ **ઔપચારિક સ્રોતો**માંથી મેળવે છે, જ્યારે **ગરીબ પરિવારો** મુખ્યત્વે **અનૌપચારિક સ્રોતો** પર આધાર રાખે છે. ગરીબો પાસે ઘણી વાર **તારણ** અને બૅન્કોને જરૂરી **દસ્તાવેજો** હોતા નથી, અને બૅન્કોને ઘણી નાની લોન આપવી મોંઘી પડે છે."),
 "s4.table.title": ("ऋण के औपचारिक और अनौपचारिक स्रोत", "શાખના ઔપચારિક અને અનૌપચારિક સ્રોતો"),
 "s4.table.body": (
  "| | औपचारिक स्रोत | अनौपचारिक स्रोत |\n|---|---|---|\n| **कौन** | बैंक और सहकारी समितियाँ | साहूकार, व्यापारी, मालिक, रिश्तेदार और दोस्त |\n"
  "| **देखरेख** | **भारतीय रिज़र्व बैंक** की देखरेख में | **कोई संस्था** देखरेख नहीं करती |\n| **ब्याज** | कम | बहुत ज़्यादा; क़र्ज़-जाल में फँसा सकता है |\n"
  "| **ज़मानत और काग़ज़ात** | आमतौर पर ज़मानत और काग़ज़ात चाहिए | अक्सर बिना ज़मानत देते हैं, पर अनुचित शर्तों पर |\n| **कौन ज़्यादा इस्तेमाल करता है** | अमीर परिवार | ग़रीब परिवार |",
  "| | ઔપચારિક સ્રોતો | અનૌપચારિક સ્રોતો |\n|---|---|---|\n| **કોણ** | બૅન્કો અને સહકારી મંડળીઓ | શાહુકારો, વેપારીઓ, માલિકો, સગાં અને મિત્રો |\n"
  "| **દેખરેખ** | **ભારતીય રિઝર્વ બૅન્ક**ની દેખરેખ હેઠળ | **કોઈ સંસ્થા** દેખરેખ રાખતી નથી |\n| **વ્યાજ** | ઓછું | ઘણું વધારે; દેવાની જાળમાં ફસાવી શકે |\n"
  "| **તારણ અને દસ્તાવેજો** | સામાન્ય રીતે તારણ અને દસ્તાવેજો જોઈએ | ઘણી વાર તારણ વિના આપે છે, પણ અયોગ્ય શરતોએ |\n| **કોણ વધુ વાપરે છે** | ધનિક પરિવારો | ગરીબ પરિવારો |"),
 "s5.thm.title": ("स्वयं सहायता समूह ग़रीबों तक ऋण कैसे पहुँचाते हैं", "સ્વસહાય જૂથો ગરીબો સુધી ધિરાણ કેવી રીતે પહોંચાડે છે"),
 "s5.thm.body": (
  "ग़रीबों, ख़ासकर ग्रामीण इलाक़ों में, को **ज़मानत** और काग़ज़ात न होने से बैंक ऋण पाने में मुश्किल होती है। **स्वयं सहायता समूह (SHG)** उनकी ऋण ज़रूरतें पूरी करने का नया तरीक़ा हैं, जो **ग्रामीण ग़रीबों, ख़ासकर महिलाओं**, को छोटे समूहों में संगठित करने और उनकी बचत इकट्ठा करने के विचार पर आधारित है।\n"
  "- एक सामान्य SHG में **15–20 सदस्य** होते हैं, आमतौर पर एक ही पड़ोस के, जो **नियमित रूप से मिलते और बचत करते** हैं। प्रति सदस्य बचत लोगों की क्षमता के अनुसार **Rs 25 से Rs 100** या उससे ज़्यादा होती है।\n"
  "- सदस्य अपनी ज़रूरतों के लिए **समूह से ही छोटे क़र्ज़** ले सकते हैं। समूह इन ऋणों पर ब्याज लेता है, पर यह **साहूकार से कम** होता है।\n"
  "- एक-दो साल बाद, अगर समूह नियमित रूप से बचत करता है, तो वह **बैंक से ऋण लेने के योग्य** हो जाता है। ऋण **समूह के नाम** पर दिया जाता है और इसका उद्देश्य सदस्यों के लिए **स्वरोज़गार** के अवसर पैदा करना है: जैसे गिरवी ज़मीन छुड़ाने, कार्यशील पूँजी (बीज, खाद, बाँस और कपड़े जैसा कच्चा माल), घर बनाने, या सिलाई मशीन, हथकरघा और पशु जैसी संपत्ति ख़रीदने के लिए छोटे ऋण।\n"
  "- **बचत और ऋण गतिविधियों से जुड़े अधिकतर महत्त्वपूर्ण फ़ैसले समूह के सदस्य लेते हैं।** समूह तय करता है कि कौन-से ऋण दिए जाएँ, उनका उद्देश्य, रक़म, ब्याज और चुकाने की समय-सारिणी। **ऋण चुकाने की ज़िम्मेदारी समूह की** होती है: न चुकाने के किसी भी मामले में दूसरे सदस्य गंभीरता से पीछा करते हैं। इसलिए बैंक SHG में संगठित ग़रीब महिलाओं को **बिना ज़मानत के भी** ऋण देने को तैयार रहते हैं।\n\n"
  "**SHG के लाभ:**\n"
  "- ये कर्ज़दारों को **ज़मानत की कमी की समस्या से उबारते** हैं।\n"
  "- इनसे विभिन्न उद्देश्यों के लिए **उचित ब्याज दर** पर **समय पर ऋण** मिलता है।\n"
  "- ये ग्रामीण ग़रीबों के संगठन की नींव हैं: ये महिलाओं को **आर्थिक रूप से आत्मनिर्भर** बनाते हैं।\n"
  "- नियमित बैठकें **स्वास्थ्य, पोषण और घरेलू हिंसा** जैसे कई सामाजिक मुद्दों पर **चर्चा का मंच** देती हैं।\n\n"
  "**बांग्लादेश का ग्रामीण बैंक:** **1970 के दशक** में **प्रोफ़ेसर मुहम्मद यूनुस** ने इसे एक छोटी परियोजना के रूप में शुरू किया; यह ग़रीबों को बिना ज़मानत छोटे ऋण देता है। **इसके लगभग सभी कर्ज़दार महिलाएँ** हैं जो समाज के सबसे ग़रीब वर्गों से हैं। इसने दिखाया है कि ग़रीब भरोसेमंद कर्ज़दार हैं। प्रोफ़ेसर यूनुस और ग्रामीण बैंक को **2006 में नोबेल शांति पुरस्कार** मिला।",
  "ગરીબોને, ખાસ કરીને ગ્રામીણ વિસ્તારોમાં, **તારણ** અને દસ્તાવેજો ન હોવાથી બૅન્ક લોન મેળવવામાં મુશ્કેલી પડે છે. **સ્વસહાય જૂથો (SHG)** તેમની ધિરાણ જરૂરિયાતો પૂરી કરવાની નવી રીત છે, જે **ગ્રામીણ ગરીબો, ખાસ કરીને સ્ત્રીઓ**, ને નાનાં જૂથોમાં સંગઠિત કરી તેમની બચત ભેગી કરવાના વિચાર પર આધારિત છે.\n"
  "- સામાન્ય SHGમાં **15–20 સભ્યો** હોય છે, સામાન્ય રીતે એક જ પડોશના, જે **નિયમિત મળે છે અને બચત કરે છે**. સભ્યદીઠ બચત લોકોની ક્ષમતા પ્રમાણે **Rs 25થી Rs 100** કે તેથી વધુ હોય છે.\n"
  "- સભ્યો પોતાની જરૂરિયાતો માટે **જૂથમાંથી જ નાની લોન** લઈ શકે. જૂથ આ લોન પર વ્યાજ લે છે, પણ તે **શાહુકાર કરતાં ઓછું** હોય છે.\n"
  "- એક-બે વર્ષ પછી, જો જૂથ નિયમિત બચત કરે, તો તે **બૅન્ક લોન મેળવવા પાત્ર** બને છે. લોન **જૂથના નામે** મંજૂર થાય છે અને તેનો હેતુ સભ્યો માટે **સ્વરોજગાર**ની તકો ઊભી કરવાનો છે: જેમ કે ગીરો મૂકેલી જમીન છોડાવવા, કાર્યકારી મૂડી (બિયારણ, ખાતર, વાંસ અને કાપડ જેવો કાચો માલ), ઘર, કે સિલાઈ મશીન, હાથશાળ અને પશુ જેવી અસ્કયામતો ખરીદવા નાની લોન.\n"
  "- **બચત અને લોન પ્રવૃત્તિઓ અંગેના મોટા ભાગના મહત્ત્વના નિર્ણયો જૂથના સભ્યો લે છે.** જૂથ નક્કી કરે છે કે કઈ લોન આપવી, તેનો હેતુ, રકમ, વ્યાજ અને ચુકવણીનું સમયપત્રક. **લોન ચૂકવવાની જવાબદારી જૂથની** હોય છે: ન ચૂકવવાના કોઈ પણ કિસ્સામાં બીજા સભ્યો ગંભીરતાથી પીછો કરે છે. તેથી બૅન્કો SHGમાં સંગઠિત ગરીબ સ્ત્રીઓને **તારણ વિના પણ** લોન આપવા તૈયાર હોય છે.\n\n"
  "**SHGના લાભ:**\n"
  "- તે દેવાદારોને **તારણના અભાવની સમસ્યામાંથી બહાર** લાવે છે.\n"
  "- તેનાથી જુદા જુદા હેતુઓ માટે **વાજબી વ્યાજ દરે** **સમયસર લોન** મળે છે.\n"
  "- તે ગ્રામીણ ગરીબોના સંગઠનનો પાયો છે: તે સ્ત્રીઓને **આર્થિક રીતે સ્વનિર્ભર** બનાવે છે.\n"
  "- નિયમિત બેઠકો **આરોગ્ય, પોષણ અને ઘરેલુ હિંસા** જેવા ઘણા સામાજિક મુદ્દાઓ પર **ચર્ચાનું મંચ** આપે છે.\n\n"
  "**બાંગ્લાદેશની ગ્રામીણ બૅન્ક:** **1970ના દાયકામાં** **પ્રોફેસર મુહમ્મદ યુનુસે** તેને નાની યોજના તરીકે શરૂ કરી; તે ગરીબોને તારણ વિના નાની લોન આપે છે. **તેના લગભગ બધા દેવાદારો સ્ત્રીઓ** છે જે સમાજના સૌથી ગરીબ વર્ગોમાંથી છે. તેણે બતાવ્યું છે કે ગરીબો વિશ્વસનીય દેવાદારો છે. પ્રોફેસર યુનુસ અને ગ્રામીણ બૅન્કને **2006માં નોબેલ શાંતિ પારિતોષિક** મળ્યું."),
 "s6.memory.title": ("याद रखने की तरकीबें", "યાદ રાખવાની યુક્તિઓ"),
 "s6.memory.body": (
  "- **वस्तु विनिमय में \"दोहरा संयोग\" चाहिए; मुद्रा इसे हटाती है** = विनिमय का माध्यम।\n- **RBI केंद्र की ओर से नोट जारी करता है; रुपये को मना नहीं किया जा सकता।**\n"
  "- **बैंक ~15% नक़द रखते हैं; बाक़ी उधार देते हैं; आय = ऋण ब्याज − जमा ब्याज।**\n- **ऋण की शर्तें \"ब्या-ज़-का-भु\"**: ब्याज, ज़मानत, काग़ज़ात, भुगतान का तरीक़ा।\n"
  "- **औपचारिक = बैंक + सहकारी (RBI देखता है); अनौपचारिक = साहूकार, व्यापारी, मालिक, रिश्तेदार, दोस्त (कोई नहीं देखता)।**\n"
  "- **SHG \"15-20, बचत, ऋण, बैंक, समूह चुकाता है\"**; ग्रामीण बैंक, यूनुस, नोबेल शांति पुरस्कार 2006।",
  "- **વસ્તુ વિનિમયમાં \"બેવડો સંયોગ\" જોઈએ; નાણું તેને દૂર કરે છે** = વિનિમયનું માધ્યમ.\n- **RBI કેન્દ્ર વતી નોટો બહાર પાડે છે; રૂપિયાનો ઇનકાર ન કરી શકાય.**\n"
  "- **બૅન્કો ~15% રોકડ રાખે છે; બાકીનું ધિરાણ આપે છે; આવક = લોન વ્યાજ − થાપણ વ્યાજ.**\n- **શાખની શરતો \"વ્યા-તા-દ-ચુ\"**: વ્યાજ, તારણ, દસ્તાવેજો, ચુકવણીની રીત.\n"
  "- **ઔપચારિક = બૅન્કો + સહકારી (RBI જુએ છે); અનૌપચારિક = શાહુકારો, વેપારીઓ, માલિકો, સગાં, મિત્રો (કોઈ જોતું નથી).**\n"
  "- **SHG \"15-20, બચત, લોન, બૅન્ક, જૂથ ચૂકવે\"**; ગ્રામીણ બૅન્ક, યુનુસ, નોબેલ શાંતિ પારિતોષિક 2006."),
 "s6.mistakes.title": ("आम ग़लतियाँ", "સામાન્ય ભૂલો"),
 "s6.mistakes.body": (
  "1. यह कहना कि भारतीय स्टेट बैंक या वित्त मंत्रालय नोट जारी करता है: **RBI** केंद्र सरकार की ओर से उन्हें जारी करता है।\n2. माँग जमा को 'मुद्रा नहीं' कहना: इनमें मुद्रा के बुनियादी गुण हैं और ये मुद्रा गिनी जाती हैं।\n"
  "3. मालिकों और रिश्तेदारों को औपचारिक ऋणदाता कहना: वे **अनौपचारिक** हैं।\n4. यह कहना कि बैंक सारी जमा नक़द रखते हैं: वे केवल लगभग **15 प्रतिशत** रखते हैं और बाक़ी उधार देते हैं।\n"
  "5. यह कहना कि SHG के फ़ैसले बैंक लेता है: फ़ैसले **सदस्य** लेते हैं।\n6. ज़मानत और ब्याज को मिलाना: ज़मानत **गिरवी रखी संपत्ति** है; ब्याज ऋण की **क़ीमत** है।",
  "1. કહેવું કે સ્ટેટ બૅન્ક ઑફ ઇન્ડિયા કે નાણાં મંત્રાલય નોટો બહાર પાડે છે: **RBI** કેન્દ્ર સરકાર વતી તે બહાર પાડે છે.\n2. માગ થાપણોને 'નાણું નહિ' કહેવું: તેમાં નાણાંનાં મૂળભૂત લક્ષણો છે અને તે નાણું ગણાય છે.\n"
  "3. માલિકો અને સગાંને ઔપચારિક ધિરાણકર્તા કહેવા: તેઓ **અનૌપચારિક** છે.\n4. કહેવું કે બૅન્કો બધી થાપણો રોકડ રાખે છે: તેઓ ફક્ત આશરે **15 ટકા** રાખે છે અને બાકીનું ધિરાણ આપે છે.\n"
  "5. કહેવું કે SHGના નિર્ણયો બૅન્ક લે છે: નિર્ણયો **સભ્યો** લે છે.\n6. તારણ અને વ્યાજને ભેળવવાં: તારણ **ગીરો મૂકેલી અસ્કયામત** છે; વ્યાજ લોનની **કિંમત** છે."),
 "s6.tip.title": ("कक्षा में करके देखें", "વર્ગમાં કરી જુઓ"),
 "s6.tip.body": (
  "वस्तु विनिमय का एक छोटा खेल खेलिए: हर छात्र को किसी वस्तु का चित्र-कार्ड दीजिए, और उनसे बिना मुद्रा के अपनी पसंद की वस्तु से अदला-बदली करने को कहिए। फिर काग़ज़ की 'मुद्रा' देकर खेल दोहराइए। चर्चा कीजिए कि मुद्रा ने आवश्यकताओं के दोहरे संयोग की ज़रूरत कैसे ख़त्म की।",
  "વસ્તુ વિનિમયની નાની રમત રમો: દરેક વિદ્યાર્થીને કોઈ વસ્તુનું ચિત્ર-કાર્ડ આપો, અને તેમને નાણાં વિના પોતાને જોઈતી વસ્તુ સાથે અદલાબદલી કરવા કહો. પછી કાગળનું 'નાણું' આપી રમત ફરી રમો. ચર્ચા કરો કે નાણાંએ જરૂરિયાતોના બેવડા સંયોગની જરૂર કેવી રીતે દૂર કરી."),
 "s6.reflection.title": ("सोचिए और समझाइए", "વિચારો અને સમજાવો"),
 "s6.reflection.body": (
  "अगर आपके इलाक़े की किसी छोटी दुकानदार को दुकान बढ़ाने के लिए Rs 20,000 चाहिए, तो वह कहाँ से उधार ले सकती है? ब्याज, ज़मानत और जोखिम के आधार पर बैंक, साहूकार और SHG की तुलना कीजिए।",
  "જો તમારા વિસ્તારની કોઈ નાની દુકાનદારને દુકાન વધારવા Rs 20,000 જોઈએ, તો તે ક્યાંથી ઉછીના લઈ શકે? વ્યાજ, તારણ અને જોખમના આધારે બૅન્ક, શાહુકાર અને SHGની સરખામણી કરો."),
 "s6.connection.title": ("आगे कहाँ", "આગળ ક્યાં"),
 "s6.connection.body": (
  "- **अध्याय 2 (भारतीय अर्थव्यवस्था के क्षेत्रक):** किसानों और छोटे उत्पादकों के लिए ऋण से रोज़गार बढ़ता है।\n- **अध्याय 4 (वैश्वीकरण):** देशों के बीच वित्त और निवेश।\n"
  "- **इतिहास अध्याय 3 (वैश्वीकरण का युग):** मुद्रा, व्यापार और विश्व अर्थव्यवस्था।",
  "- **પ્રકરણ 2 (ભારતીય અર્થતંત્રનાં ક્ષેત્રો):** ખેડૂતો અને નાના ઉત્પાદકો માટે ધિરાણથી રોજગાર વધે છે.\n- **પ્રકરણ 4 (વૈશ્વિકીકરણ):** દેશો વચ્ચે નાણાં અને રોકાણ.\n"
  "- **ઇતિહાસ પ્રકરણ 3 (વૈશ્વિક વિશ્વનું નિર્માણ):** નાણું, વેપાર અને વિશ્વ અર્થતંત્ર."),
 "s6.mastery.title": ("महारत चुनौती", "નિપુણતા પડકાર"),
 "s6.mastery.body": (
  "'सस्ता और सामर्थ्य के अनुकूल ऋण देश के विकास के लिए बहुत ज़रूरी है।' लगभग 120 शब्दों में पुष्टि कीजिए।\n\n"
  "**आदर्श उत्तर:** ऋण लोगों को उत्पादन का ख़र्च पूरा करने और ज़्यादा कमाने में मदद करता है, जैसे सलीम ने त्योहार का ऑर्डर पूरा करके किया। पर अनौपचारिक ऋण महँगा है: साहूकार बहुत ऊँचा ब्याज लेते हैं, जैसे 5 प्रतिशत मासिक, इसलिए कर्ज़दार की कमाई का बड़ा हिस्सा ऋण चुकाने में जाता है। "
  "अगर फ़सल ख़राब हो, जैसे स्वप्ना के साथ हुआ, तो कर्ज़दार क़र्ज़-जाल में फँस जाता है और ज़मीन खो सकता है। ऊँचा ब्याज लोगों को नए उद्यम शुरू करने से भी रोकता है। "
  "बैंक और सहकारी समितियाँ कम दर पर ऋण देती हैं और RBI उनकी देखरेख करता है, इसलिए औपचारिक ऋण का विस्तार, ख़ासकर ग्रामीण ग़रीबों तक, आय बढ़ाता है। स्वयं सहायता समूह ग़रीबों को बिना ज़मानत ऐसे ऋण दिलाने में मदद करते हैं। इस तरह सस्ता ऋण खेती, छोटे उद्योग और रोज़गार को सहारा देता है।",
  "'સસ્તી અને પરવડે તેવી શાખ દેશના વિકાસ માટે ખૂબ જરૂરી છે.' આશરે 120 શબ્દોમાં સમર્થન કરો.\n\n"
  "**આદર્શ જવાબ:** શાખ લોકોને ઉત્પાદનનો ખર્ચ પૂરો કરવામાં અને વધુ કમાવામાં મદદ કરે છે, જેમ સલીમે તહેવારનો ઑર્ડર પૂરો કરીને કર્યું. પણ અનૌપચારિક શાખ મોંઘી છે: શાહુકારો ઘણું ઊંચું વ્યાજ લે છે, જેમ કે 5 ટકા માસિક, તેથી દેવાદારની કમાણીનો મોટો ભાગ લોન ચૂકવવામાં જાય છે. "
  "જો પાક નિષ્ફળ જાય, જેમ સ્વપ્ના સાથે થયું, તો દેવાદાર દેવાની જાળમાં ફસાય છે અને જમીન ગુમાવી શકે. ઊંચું વ્યાજ લોકોને નવા ધંધા શરૂ કરતાં પણ રોકે છે. "
  "બૅન્કો અને સહકારી મંડળીઓ ઓછા દરે ધિરાણ આપે છે અને RBI તેમની દેખરેખ રાખે છે, તેથી ઔપચારિક શાખનો વિસ્તાર, ખાસ કરીને ગ્રામીણ ગરીબો સુધી, આવક વધારે છે. સ્વસહાય જૂથો ગરીબોને તારણ વિના આવી લોન મેળવવામાં મદદ કરે છે. આમ સસ્તી શાખ ખેતી, નાના ઉદ્યોગો અને રોજગારને ટેકો આપે છે."),
 "s6.summary.title": ("अध्याय सारांश", "પ્રકરણ સારાંશ"),
 "s6.summary.body": (
  "- मुद्रा विनिमय का माध्यम है जो आवश्यकताओं के दोहरे संयोग की ज़रूरत हटाती है; आधुनिक मुद्रा में करेंसी और माँग जमा शामिल हैं।\n"
  "- RBI सरकार की ओर से करेंसी जारी करता है; रुपया वैध मुद्रा है जिसे मना नहीं किया जा सकता।\n"
  "- बैंक लगभग 15 प्रतिशत जमा नक़द रखते हैं और बाक़ी उधार देते हैं; ऋण ब्याज और जमा ब्याज का अंतर उनकी मुख्य आय है।\n"
  "- ऋण कमाई बढ़ा सकता है या क़र्ज़-जाल में फँसा सकता है; ऋण की शर्तों में ब्याज, ज़मानत, काग़ज़ात और भुगतान शामिल हैं।\n"
  "- औपचारिक ऋण (बैंक, सहकारी समितियाँ) RBI की देखरेख में और सस्ता है; अनौपचारिक ऋण महँगा और अनियंत्रित है; ग़रीब अनौपचारिक ऋण पर ज़्यादा निर्भर हैं।\n"
  "- स्वयं सहायता समूह ग़रीबों, ख़ासकर महिलाओं, को बिना ज़मानत ऋण दिलाते और आत्मनिर्भर बनाते हैं।",
  "- નાણું વિનિમયનું માધ્યમ છે જે જરૂરિયાતોના બેવડા સંયોગની જરૂર દૂર કરે છે; આધુનિક નાણાંમાં ચલણ અને માગ થાપણો સમાયેલાં છે.\n"
  "- RBI સરકાર વતી ચલણ બહાર પાડે છે; રૂપિયો કાયદેસર ચલણ છે જેનો ઇનકાર ન કરી શકાય.\n"
  "- બૅન્કો આશરે 15 ટકા થાપણો રોકડ રાખે છે અને બાકીનું ધિરાણ આપે છે; લોન વ્યાજ અને થાપણ વ્યાજનો તફાવત તેમની મુખ્ય આવક છે.\n"
  "- શાખ કમાણી વધારી શકે કે દેવાની જાળમાં ફસાવી શકે; શાખની શરતોમાં વ્યાજ, તારણ, દસ્તાવેજો અને ચુકવણી સમાયેલાં છે.\n"
  "- ઔપચારિક શાખ (બૅન્કો, સહકારી મંડળીઓ) RBIની દેખરેખ હેઠળ અને સસ્તી છે; અનૌપચારિક શાખ મોંઘી અને અનિયંત્રિત છે; ગરીબો અનૌપચારિક શાખ પર વધુ આધાર રાખે છે.\n"
  "- સ્વસહાય જૂથો ગરીબો, ખાસ કરીને સ્ત્રીઓ, ને તારણ વિના લોન અપાવે છે અને સ્વનિર્ભર બનાવે છે."),
 "s6.examtips.title": ("बोर्ड परीक्षा के सुझाव", "બોર્ડ પરીક્ષા માટેની ટિપ્સ"),
 "s6.examtips.body": (
  "- 2025-26 के प्रतिदर्श प्रश्न-पत्र में पूछा गया कि भारत में करेंसी नोट कौन जारी करता है (RBI; उत्तर B), आवश्यकताओं का दोहरा संयोग वस्तु विनिमय को क्यों सीमित करता है (उत्तर A), और 3 अंक का प्रश्न कि औपचारिक ऋण का विस्तार और सब तक पहुँच क्यों ज़रूरी है।\n"
  "- 3/5 अंक के पसंदीदा प्रश्न: मुद्रा दोहरे संयोग को कैसे सुलझाती है, बैंक मध्यस्थ के रूप में, ऋण की शर्तें, औपचारिक बनाम अनौपचारिक ऋण, RBI की भूमिका, SHG।\n"
  "- अपने उत्तरों में पाठ्यपुस्तक के उदाहरण (सलीम, स्वप्ना, श्यामल, रमा, अरुण) इस्तेमाल करें।",
  "- 2025-26ના નમૂનાના પ્રશ્નપત્રમાં પુછાયું કે ભારતમાં ચલણી નોટો કોણ બહાર પાડે છે (RBI; જવાબ B), જરૂરિયાતોનો બેવડો સંયોગ વસ્તુ વિનિમયને કેમ મર્યાદિત કરે છે (જવાબ A), અને 3 ગુણનો પ્રશ્ન કે ઔપચારિક ધિરાણનો વિસ્તાર અને બધા સુધી પહોંચ કેમ જરૂરી છે.\n"
  "- 3/5 ગુણના પ્રિય પ્રશ્નો: નાણું બેવડો સંયોગ કેવી રીતે ઉકેલે છે, બૅન્કો મધ્યસ્થી તરીકે, શાખની શરતો, ઔપચારિક સામે અનૌપચારિક શાખ, RBIની ભૂમિકા, SHG.\n"
  "- તમારા જવાબોમાં પાઠ્યપુસ્તકનાં ઉદાહરણો (સલીમ, સ્વપ્ના, શ્યામલ, રમા, અરુણ) વાપરો."),
 "s6.flash1.front": ("आवश्यकताओं का दोहरा संयोग क्या है?", "જરૂરિયાતોનો બેવડો સંયોગ શું છે?"),
 "s6.flash1.back": ("वस्तु विनिमय की वह स्थिति जिसमें जो वस्तु एक व्यक्ति बेचना चाहता है, ठीक वही दूसरा ख़रीदना चाहता है।", "વસ્તુ વિનિમયની એવી સ્થિતિ જેમાં જે વસ્તુ એક વ્યક્તિ વેચવા માગે છે, બરાબર તે જ બીજી ખરીદવા માગે છે."),
 "s6.flash2.front": ("समर्थक ऋणाधार क्या है?", "તારણ શું છે?"),
 "s6.flash2.back": ("कर्ज़दार की संपत्ति (ज़मीन, इमारत, गाड़ी, पशु, जमा) जिसे वह ऋण चुकाने तक गारंटी के रूप में गिरवी रखता है।", "દેવાદારની અસ્કયામત (જમીન, મકાન, વાહન, પશુધન, થાપણો) જે તે લોન ચૂકવાય ત્યાં સુધી ખાતરી તરીકે ગીરો મૂકે છે."),
 "s6.flash3.front": ("क़र्ज़-जाल क्या है?", "દેવાની જાળ શું છે?"),
 "s6.flash3.back": ("ऐसी स्थिति जिसमें कर्ज़दार ऋण नहीं चुका पाता, क़र्ज़ बढ़ता जाता है, और वह पहले से बुरी हालत में पहुँच जाता है।", "એવી સ્થિતિ જેમાં દેવાદાર લોન ચૂકવી શકતો નથી, દેવું વધતું જાય છે, અને તે પહેલાં કરતાં ખરાબ સ્થિતિમાં મુકાય છે."),
 "s6.flash4.front": ("माँग जमा क्या हैं?", "માગ થાપણો શું છે?"),
 "s6.flash4.back": ("बैंक खातों की वह जमा जो माँग पर निकाली जा सकती है; इन्हें मुद्रा माना जाता है और चेक से इस्तेमाल किया जा सकता है।", "બૅન્ક ખાતાંની એવી થાપણો જે માગણી થતાં ઉપાડી શકાય; તેને નાણું ગણાય છે અને ચેકથી વાપરી શકાય છે."),
}
